  vColor = mix(vec3(1.0, 0.97, 0.86), aColor, smoothstep(0.015, 0.08, t)); // brief birth pop, then stay SATURATED
  vColor *= 0.88 + 0.24 * fract(aSeed * 3.77);      // slight per-spark tonal variety
  vLife = life;
